SELECT COUNT(*)
FROM erp_payment_bill
WHERE student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
  AND bill_type = #{billType}
  AND status IN ('issued', 'approved', 'partial');

SELECT COALESCE(SUM(amount), 0) as billed_amount
FROM erp_payment_bill
WHERE payment_key = #{paymentKey}
AND yy = #{yy}
AND mm = #{mm}
AND bill_type = #{billType}
AND status IN

    #{status}

SELECT COUNT(*) as count,
payment_key AS paymnetKey,
student_id AS studentId,
bill_id AS billId
FROM erp_payment_bill
WHERE student_id = #{studentId}
  AND payment_key = #{paymentKey}
  AND yy = #{yy}
  AND mm = #{mm}
  AND bill_type = 'EDU_FEE'
  AND status in ('issued')
GROUP BY payment_key, student_id, bill_id

select epd.amount - ISNULL((pm.card_amount + pm.cash_amount + pm.transfer_amount), 0)
from erp_payment_detail epd
         join erp_payment p on epd.payment_key = p.payment_key
         LEFT join erp_payment_manual pm on pm.payment_key = p.payment_key AND p.student_id = pm.student_id
where p.student_id = #{studentId}
  and p.yy = #{yy}
  and p.mm = #{mm}
  and epd.item_type = 'EDU_FEE'

SELECT count(*)
FROM erp_payment_manual
where student_id = #{studentId}
  AND payment_key = #{paymentKey}
  AND yy = #{yy}
  AND mm = #{mm}

SELECT status
from erp_payment_bill
WHERE payment_key = #{paymentKey}
  AND student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
  AND status NOT IN ('destroyed')
  AND bill_type = 'BOOK_FEE'

