SELECT s.student_id AS studentId, (p.yy + '-' + p.mm) AS classDate, s.student_name AS studentName, p.payment_key AS paymentKey,
STUFF(( SELECT ', ' + sub.class_name FROM ( SELECT DISTINCT cc2.class_name, cc2.class_type FROM erp_time_table_assign ta2 JOIN erp_time_table t2 ON ta2.time_table_key = t2.time_table_key JOIN erp_class_code cc2 ON cc2.class_key = CASE WHEN t2.class_key = 'COM' THEN ta2.class_key ELSE t2.class_key END WHERE ta2.student_id = p.student_id AND t2.yy = p.yy AND t2.mm = p.mm) AS sub ORDER BY sub.class_type FOR XML PATH (''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS subject, hu.user_name AS hanTeacher, bu.user_name AS bookTeacher, p.amount AS amount, p.status, p.paid_date AS paidDate, edu.han_material_fee AS hanMaterialFee, edu.book_material_fee AS booKMaterialFee, edu.han_edu_fee AS hanFee, edu.book_edu_fee AS bookFee
FROM erp_payment p LEFT JOIN ( SELECT pd.payment_key, -- 교육비 MAX(CASE WHEN pd.item_type = 'EDU_FEE' AND pd.class_type = '1' THEN pd.amount END) AS han_edu_fee, MAX(CASE WHEN pd.item_type = 'EDU_FEE' AND pd.class_type = '2' THEN pd.amount END) AS book_edu_fee, -- 교재비 MAX(CASE WHEN pd.item_type = 'BOOK_FEE' AND pd.class_type = '1' THEN pd.amount END) AS han_material_fee, MAX(CASE WHEN pd.item_type = 'BOOK_FEE' AND pd.class_type = '2' THEN pd.amount END) AS book_material_fee
FROM erp_payment_detail pd GROUP BY pd.payment_key) AS edu ON p.payment_key = edu.payment_key JOIN erp_student s ON p.student_id = s.student_id JOIN erp_teacher_assign ta ON s.student_id = ta.student_id LEFT JOIN erp_user hu ON ta.assign_han_teacher = hu.user_code LEFT JOIN erp_user bu ON ta.assign_book_teacher = bu.user_code WHERE s.center_code = #{centerCode} AND p.yy = #{yy} AND p.mm = #{mm}
AND p.student_id = #{studentId}
ORDER BY classDate DESC;

SELECT TOP ${count} * FROM (select p.bill_id AS billId, (p.yy + '-' + p.mm) AS inym, 'S' AS gb, p.approved_date AS indate, p.han_amount AS inmoney, CASE WHEN p.product_name = '교육비' THEN 'S' WHEN p.product_name = '교재비' THEN 'B' ELSE null END AS gubun, p.created_at from erp_payment p WHERE p.han_amount IS NOT NULL AND p.student_id = #{studentId} AND P.approved_date IS NOT NULL
UNION ALL
select p.bill_id AS billId, (p.yy + '-' + p.mm) AS inym, 'I' AS gb, p.approved_date AS indate, p.book_amount AS inmoney, CASE WHEN p.product_name = '교육비' THEN 'S' WHEN p.product_name = '교재비' THEN 'B' ELSE null END AS gubun, p.created_at from erp_payment p WHERE p.book_amount IS NOT NULL AND p.student_id = #{studentId}) AS combined AND P.approved_date IS NOT NULL ORDER BY combined.billId ASC;

SELECT pb.bill_id as billId, 'bill' as type, pb.payment_key, pb.student_id, s.student_name as studentName, pb.bill_type as billType, pb.expire_date as expireDate, STUFF(STUFF(LEFT(pc.appr_date, 8), 5, 0, '-'), 8, 0, '-') as paidDate, pb.amount, card.card_name as cardName, pb.status, pb.created_at as createdAt FROM erp_payment_bill pb JOIN erp_student s on pb.student_id = s.student_id LEFT JOIN erp_payment_callback pc on pb.bill_id = pc.bill_id LEFT JOIN erp_card_code card on pc.appr_issuer = card.card_code WHERE pb.student_id = #{studentId}
UNION ALL
SELECT pm.bill_id as billId, 'manual' as type, pm.payment_key, pm.student_id as student_id, s.student_name as studentName, 'EDU_FEE' as billType, null as expireDate, pm.paid_date as paidDate, pm.card_amount + pm.cash_amount + pm.transfer_amount as amount, card.card_name as cardName, pm.status, pm.created_at as createdAt FROM erp_payment_manual pm JOIN erp_student s on pm.student_id = s.student_id LEFT JOIN erp_card_code card on pm.card_name = card.card_code WHERE pm.student_id = #{studentId} ORDER BY createdAt DESC;

